const email = $input.item.json;

const from = email.headers?.from || email.from?.text || (typeof email.from === 'string' ? email.from : 'Unknown sender');
const subject = email.subject || 'No subject';
const date = email.date || email.headers?.date || new Date().toISOString();
const body = email.text || email.snippet || '';
const bodyHtml = email.textAsHtml || email.html || '';

function stripHtml(html) {
  return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

const bodyText = body || stripHtml(bodyHtml) || 'No content';
const textForLink = (email.html || email.textAsHtml || email.text || email.snippet || '').toString();
const driveMatch = textForLink.match(/drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?id=)([a-zA-Z0-9_-]+)/i);
const driveFileId = driveMatch ? driveMatch[1] : null;

const plain = [
  'IMPORTANT EMAIL BACKUP',
  '======================',
  '',
  'From: ' + from,
  'Subject: ' + subject,
  'Date: ' + date,
  'Message ID: ' + (email.id || ''),
  '',
  '--- Message ---',
  '',
  bodyText,
].join('\n');

function escapePdf(text) {
  return String(text)
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)')
    .replace(/[^\x00-\x7F]/g, '?');
}

function wrapLines(text, maxLen = 95) {
  const lines = [];
  for (const raw of text.split(/\r?\n/)) {
    let part = raw;
    while (part.length > maxLen) {
      lines.push(part.slice(0, maxLen));
      part = part.slice(maxLen);
    }
    lines.push(part);
  }
  return lines.slice(0, 55);
}

function buildPdfBuffer(text) {
  const lines = wrapLines(text);
  let stream = 'BT\n/F1 11 Tf\n';
  stream += '50 750 Td\n';
  lines.forEach((line, i) => {
    if (i > 0) stream += '0 -14 Td\n';
    stream += '(' + escapePdf(line) + ') Tj\n';
  });
  stream += 'ET';

  const streamLen = Buffer.byteLength(stream, 'binary');
  const parts = [
    '1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n',
    '2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n',
    '3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>\nendobj\n',
    '4 0 obj\n<< /Length ' + streamLen + ' >>\nstream\n' + stream + 'endstream\nendobj\n',
    '5 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n',
  ];

  let pdf = '%PDF-1.4\n';
  const offsets = [0];
  for (const part of parts) {
    offsets.push(Buffer.byteLength(pdf, 'binary'));
    pdf += part;
  }
  const xrefPos = Buffer.byteLength(pdf, 'binary');
  pdf += 'xref\n0 ' + (parts.length + 1) + '\n';
  pdf += '0000000000 65535 f \n';
  for (let i = 1; i <= parts.length; i++) {
    pdf += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
  }
  pdf += 'trailer\n<< /Size ' + (parts.length + 1) + ' /Root 1 0 R >>\nstartxref\n' + xrefPos + '\n%%EOF';

  return Buffer.from(pdf, 'binary');
}

const datePrefix = new Date().toISOString().split('T')[0];
const pdfFileName = datePrefix + '_' + (email.id || 'email') + '_important.pdf';
const pdfBuffer = buildPdfBuffer(plain);

return {
  json: {
    ...email,
    pdfFileName,
    emailFrom: from,
    emailSubject: subject,
    emailPreview: bodyText.slice(0, 200),
    driveFileId,
  },
  binary: {
    data: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: pdfFileName,
    },
  },
};
